mapper.select:
SELECT COUNT(*) 
FROM T_REPORT
WHERE REPORTER_NUM = #{reporterNum}
  AND TARGET_TYPE = #{targetType}
  AND TARGET_NUM = #{targetNum}

mapper.insert:
INSERT INTO T_REPORT (
    REPORT_NUM, REPORTER_NUM, TARGET_TYPE, TARGET_NUM, REPORT_REASON, REPORT_STATUS, REPORT_DATE
) VALUES (
    SEQ_T_REPORT.NEXTVAL, #{reporterNum}, #{targetType}, #{targetNum}, #{reportReason}, 'PENDING', SYSDATE
)
